  'Medical-Surgical Nursing I',
  'This course introduces safe, evidence-informed adult medical-surgical nursing care for common medical and surgical conditions. Students integrate focused assessment, pathophysiology, pharmacology, diagnostic data, clinical judgment, patient education, interprofessional communication, and care planning. The course emphasizes clinical reasoning, prioritization, deterioration recognition, quality and safety, culturally responsive care, and simulation-based practice.',
  $msn1json${"slug": "medical-surgical-nursing-i", "title": "Medical-Surgical Nursing I", "description": "This course introduces safe, evidence-informed adult medical-surgical nursing care for common medical and surgical conditions. Students integrate focused assessment, pathophysiology, pharmacology, diagnostic data, clinical judgment, patient education, interprofessional communication, and care planning. The course emphasizes clinical reasoning, prioritization, deterioration recognition, quality and safety, culturally responsive care, and simulation-based practice.", "topics": [{"id": "6484010d-9ecb-4441-8f0c-d5c8e2ae6b8b", "type": "topic", "title": "Professional Adult Health Nursing and Clinical Judgment", "description": "Students learn the adult medical-surgical nurse's role in safe, evidence-informed, patient-centered care for common conditions.", "children": [{"id": "833854c8-f23f-4053-9f1e-23af2c69f812", "type": "subtopic", "title": "Adult-health nursing role", "description": "The point is to understand med-surg nursing as coordinated care for adults with common acute and chronic conditions.", "children": [{"id": "da2466f8-ef25-4e44-9e24-2c8a331303a5", "type": "concept", "title": "Health promotion, acute care, chronic illness, and rehabilitation"}, {"id": "c8228877-a258-4ed3-b7a0-eecc12a2d101", "type": "concept", "title": "Nursing process and clinical judgment model"}, {"id": "42a3af29-d999-4b9b-8f27-98739fc06975", "type": "concept", "title": "Scope, standards, accountability, and patient advocacy"}]}, {"id": "736eae17-325e-4874-ad49-d379abf208ee", "type": "subtopic", "title": "Patient-centered care", "description": "Students learn to adapt care to the person, family, culture, function, and goals.", "children": [{"id": "3e04a1ce-132e-4e23-a61d-abc37b860e34", "type": "concept", "title": "Therapeutic communication"}, {"id": "68e89543-f6e4-4f0b-b052-c0b9f21bee9c", "type": "concept", "title": "Cultural humility and health literacy"}, {"id": "1c5e391e-ff3e-44c2-956e-951f96cdeb92", "type": "concept", "title": "Shared decision-making and patient preferences"}]}, {"id": "93477c20-4fb9-4e5d-81e6-94074434e08c", "type": "subtopic", "title": "Clinical reasoning foundation", "description": "A strong med-surg course teaches students to notice, interpret, respond, and evaluate.", "children": [{"id": "8384f3b7-4e84-4840-8afa-d8bef61fb621", "type": "concept", "title": "Cue recognition"}, {"id": "4a066050-88a3-4510-a0ec-9128e7eb0a35", "type": "concept", "title": "Hypothesis generation"}, {"id": "a3cae7ab-8da5-48de-97cd-adfb48c2070e", "type": "concept", "title": "Planning, intervention, and evaluation"}]}]}, {"id": "d9da3381-6121-430c-8e72-cbe2aa69916d", "type": "topic", "title": "Assessment, Prioritization, Documentation, and Interprofessional Communication", "description": "This module strengthens focused assessment, clinical reasoning, prioritization, SBAR, and escalation habits.", "children": [{"id": "955977c2-306e-4ba9-b31e-6bea0d4a3a13", "type": "subtopic", "title": "Focused assessment", "description": "Students learn to identify the most relevant data for a patient's problem.", "children": [{"id": "4ceeac7b-cc7c-4958-b029-dbfcee3b7bb8", "type": "concept", "title": "Health history and chief concern"}, {"id": "608f891a-7c74-45ef-a8ae-dea8741c9139", "type": "concept", "title": "Vital signs, pain, oxygenation, perfusion, neurologic status, and functional status"}, {"id": "0694f05d-a5b5-46b9-9ecb-956e46df8653", "type": "concept", "title": "Focused head-to-toe and system-based assessment"}]}, {"id": "f7fc5ba4-2606-402a-af00-3f0e9d791050", "type": "subtopic", "title": "Prioritization", "description": "The gist is deciding what matters first when multiple needs compete.", "children": [{"id": "74789048-64fd-4486-bbe1-941672a7112a", "type": "concept", "title": "ABCs, safety, and unstable versus stable cues"}, {"id": "92b6091b-995e-473b-b63c-365fa536c102", "type": "concept", "title": "Maslow, acute versus chronic, and urgent versus expected findings"}, {"id": "bf6f4c9a-45c2-4ee3-ad76-2c035820309f", "type": "concept", "title": "NCLEX-style prioritization and clinical judgment"}]}, {"id": "64e96cd8-29a6-4db3-a725-e56734a4919e", "type": "subtopic", "title": "Communication and documentation", "description": "Clear communication protects patients and makes care visible.", "children": [{"id": "139eca5b-94d4-478d-aed2-87eb18e7710b", "type": "concept", "title": "SBAR and closed-loop communication"}, {"id": "de54c752-98b4-4845-85fb-89f25790356d", "type": "concept", "title": "Nursing notes, care plans, and handoff"}, {"id": "2ae8df3f-7c43-4915-bfbf-59b2d870ed0c", "type": "concept", "title": "Provider notification and escalation documentation"}]}]}, {"id": "729b52ab-aa46-4b36-836e-d01bb4abc867", "type": "topic", "title": "Safety, Infection Prevention, Mobility, Skin Integrity, and Care Transitions", "description": "Students connect fundamentals skills to adult acute-care risks such as falls, infection, pressure injury, and discharge breakdowns.", "children": [{"id": "f1839577-c9de-40f3-a1be-8b337640f627", "type": "subtopic", "title": "Patient safety", "description": "Students learn routines that prevent common inpatient harm.", "children": [{"id": "8fccb5ef-2739-417b-b100-57d0cfc92ed1", "type": "concept", "title": "Fall prevention"}, {"id": "45872502-ec40-48db-82f4-f23eb83d8faa", "type": "concept", "title": "Medication safety and two-identifier checks"}, {"id": "37c2d64d-6a7a-447f-a5b7-588a88348981", "type": "concept", "title": "Restraint alternatives and safe environment"}]}, {"id": "d3db2f52-3b9d-4499-9aa4-05d1b2748eda", "type": "subtopic", "title": "Infection prevention", "description": "Infection control is a daily clinical discipline, not a one-time checklist.", "children": [{"id": "96237a6f-e7f3-4590-960d-f4ea2763a5aa", "type": "concept", "title": "Standard and transmission-based precautions"}, {"id": "0af3c2d3-8654-45da-b86a-6abf65b81d5c", "type": "concept", "title": "Hand hygiene and PPE"}, {"id": "4aec63a