"4c386b15-b6cd-4d20-8a2b-44f1c5d9f105", "type": "concept", "title": "Inflammatory bowel disease and diverticular disease"}, {"id": "8dc07d5d-006d-4bd0-9256-bd90c01c0c20", "type": "concept", "title": "Gallbladder, liver, pancreatitis, and bowel obstruction overview"}]}, {"id": "ddfbc51c-263f-4cb6-ba42-104ae138f09c", "type": "subtopic", "title": "Nutrition and therapeutic care", "description": "Nutrition is both prevention and treatment in med-surg nursing.", "children": [{"id": "1babf53e-959b-4485-9750-0c8469302215", "type": "concept", "title": "Diet progression and enteral nutrition awareness"}, {"id": "af1321e7-202b-4952-8efb-2dba2e8ee435", "type": "concept", "title": "NPO, aspiration precautions, and swallowing risk"}, {"id": "7264390d-b15d-49cd-903d-6c0079984559", "type": "concept", "title": "Patient teaching for diet, medications, and symptom monitoring"}]}]}, {"id": "2e43f72e-c988-4892-ba91-6fba08031770", "type": "topic", "title": "Endocrine Disorders: Diabetes and Thyroid Conditions", "description": "Students learn nursing management for common endocrine problems, with special attention to glucose safety.", "children": [{"id": "c40fcc8b-8ae1-4f00-a016-339fe6ffba32", "type": "subtopic", "title": "Diabetes foundations", "description": "Students learn glucose regulation and the difference between routine and urgent diabetes care.", "children": [{"id": "12d15baf-7cf2-4979-9fa6-1f9b86eb268a", "type": "concept", "title": "Type 1, type 2, and insulin resistance"}, {"id": "9f790fa3-5d23-4797-9548-534283887aa3", "type": "concept", "title": "Hyperglycemia, hypoglycemia, DKA, and HHS overview"}, {"id": "803af4cf-8798-4638-899f-9cb7ca755d3f", "type": "concept", "title": "A1C, point-of-care glucose, and sick-day concepts"}]}, {"id": "efedc8da-5c60-47c8-9288-1490b1dc5d96", "type": "subtopic", "title": "Medication and safety", "description": "Diabetes nursing requires careful timing, monitoring, and teaching.", "children": [{"id": "173e6824-d0d0-4ab9-8e5a-1d4bcd8c4666", "typ