set
  title = 'Medical-Surgical Nursing I',
  goal = 'Medical-Surgical Nursing I',
  summary = 'This course introduces safe, evidence-informed adult medical-surgical nursing care for common medical and surgical conditions. Students integrate focused assessment, pathophysiology, pharmacology, diagnostic data, clinical judgment, patient education, interprofessional communication, and care planning. The course emphasizes clinical reasoning, prioritization, deterioration recognition, quality and safety, culturally responsive care, and simulation-based practice.',
  data = $msn1json${"slug": "medical-surgical-nursing-i", "title": "Medical-Surgical Nursing I", "description": "This course introduces safe, evidence-informed adult medical-surgical nursing care for common medical and surgical conditions. Students integrate focused assessment, pathophysiology, pharmacology, diagnostic data, clinical judgment, patient education, interprofessional communication, and care planning. The course emphasizes clinical reasoning, prioritization, deterioration recognition, quality and safety, culturally responsive care, and simulation-based practice.", "topics": [{"id": "6484010d-9ecb-4441-8f0c-d5c8e2ae6b8b", "type": "topic", "title": "Professional Adult Health Nursing and Clinical Judgment", "description": "Students learn the adult medical-surgical nurse's role in safe, evidence-informed, patient-centered care for common conditions.", "children": [{"id": "833854c8-f23f-4053-9f1e-23af2c69f812", "type": "subtopic", "title": "Adult-health nursing role", "description": "The point is to understand med-surg nursing as coordinated care for adults with common acute and chronic conditions.", "children": [{"id": "da2466f8-ef25-4e44-9e24-2c8a331303a5", "type": "concept", "title": "Health promotion, acute care, chronic illness, and rehabilitation"}, {"id": "c8228877-a258-4ed3-b7a0-eecc12a2d101", "type": "concept", "title": "Nursing process and clinical judgment model"}, {"id": "42a3af29-d999-4b9b-8f27-98739fc06975", "type": "concept", "title": "Scope, standards, accountability, and patient advocacy"}]}, {"id": "736eae17-325e-4874-ad49-d379abf208ee", "type": "subtopic", "title": "Patient-centered care", "description": "Students learn to adapt care to the person, family, culture, function, and goals.", "children": [{"id": "3e04a1ce-132e-4e23-a61d-abc37b860e34", "type": "concept", "title": "Therapeutic communication"}, {"id": "68e89543-f6e4-4f0b-b052-c0b9f21bee9c", "type": "concept", "title": "Cultural humility and health literacy"}, {"id": "1c5e391e-ff3e-